function birthday(n){let no=1;for(let j=0;j<n;j++)no*=((365-j)/365);return 1-no}
function binomial(k,p){let c=1;for(let j=1;j<=k;j++)c=c*(10-j+1)/j;return c*Math.pow(p,k)*Math.pow(1-p,10-k);}
