function save(){safeSave(window.localStorage,state)}
function lessonSteps(m,ls){
 const resumeIndex=resumeStepIndex(m,ls);
 return `<div class="steps-strip" aria-label="Шаги урока">${m.steps.map((s,i)=>{const current=i===ls.index,resume=!current&&i===resumeIndex,available=!current&&(ls.doneSteps.includes(i)||resume),tag=available?'button':'span',attrs=available?` data-step-target="${i}" aria-label="${resume?'Продолжить с шага':'Открыть пройденный шаг'} ${i+1}: ${esc(s.title)}"`:current?' aria-current="step" tabindex="-1"':'';return `<${tag} class="step-dot ${current?'now':''} ${ls.doneSteps.includes(i)?'cleared':''} ${resume?'resume':''}" title="${resume?`Продолжить: ${esc(s.title)}`:esc(s.title)}"${attrs}>${ls.doneSteps.includes(i)?icon('check'):i+1}</${tag}>`}).join('')}<span class="step-count">Шаг ${ls.index+1} из ${m.steps.length}</span></div>`;
}
function resumeStepIndex(m,ls){if(ls.completedAt)return m.steps.length-1;const furthest=ls.doneSteps.length?Math.max(...ls.doneSteps)+1:0;return Math.min(furthest,m.steps.length-1)}
function proofMarkup(step){return `<div class="proof-builder">${step.groups.map(group=>{
 const selected=proof[group.id]||[];
 return `<section class="proof-lane"><h4>${esc(group.title)}</h4><div class="proof-sequence" aria-label="Собранная цепочка">${selected.length?selected.map((id,i)=>{const card=group.cards.find(c=>c.id===id);return `<button data-proof-remove="${group.id}" data-proof-index="${i}"><span>${i+1}</span>${esc(card.text)}</button>`}).join(''):'<p>Нажимай карточки ниже, чтобы собрать цепочку.</p>'}</div><div class="proof-bank">${group.cards.map(card=>`<button data-proof-add="${group.id}" data-proof-card="${card.id}" ${selected.includes(card.id)?'disabled':''}>${esc(card.text)}</button>`).join('')}</div></section>`}).join('')}</div>`}
function proseBlocks(value){return String(value??'').trim().split(/\n\s*\n/).filter(Boolean).map(block=>`<p>${esc(block).replaceAll('\n','<br>')}</p>`).join('')}
function sourceTableMarkup(table){return `<figure class="source-table-figure"><div class="source-table-scroll" tabindex="0" role="region" aria-label="${esc(table.caption)}"><table class="source-data-table"><caption>${esc(table.caption)}</caption><thead><tr><th scope="col">${renderMathMarkdown(table.corner,{display:false})}</th>${table.columns.map(value=>`<th scope="col">${renderMathMarkdown(value,{display:false})}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr><th scope="row">${renderMathMarkdown(row[0],{display:false})}</th>${row.slice(1).map(value=>`<td class="${value==='?'?'table-unknown':''}">${value==='?'?'<span aria-label="нужно найти">?</span>':renderMathMarkdown(value,{display:false})}</td>`).join('')}</tr>`).join('')}</tbody></table></div><figcaption>Последний столбец и последняя строка оставлены для вычисления маргинальных вероятностей.</figcaption></figure>`}
function sourceStatement(task){if(!task.sourceTable)return `<div class="source-copy">${proseBlocks(task.statement)}</div>`;const marker='изображена в таблице:',start=task.statement.indexOf(marker),tail=task.statement.search(/\n\s*\(a\)/);const intro=start>=0?task.statement.slice(0,start+marker.length):task.statement;const rest=tail>=0?task.statement.slice(tail):'';return `<div class="source-copy">${proseBlocks(intro)}${sourceTableMarkup(task.sourceTable)}${proseBlocks(rest)}</div>`}
function sourceContext(task){return `<details class="source-context" ${sourceExpanded?'open':''}><summary>Полное условие задачи</summary><div class="source-context-body">${sourceStatement(task)}</div></details>`}
