function binomialView(){const p=experiment.errorP,vals=Array.from({length:11},(_,i)=>binomial(i,p)),max=Math.max(...vals,.01);return `${conceptPrediction('Прогноз: что произойдёт со столбиками при росте p?',[['right','Масса сдвинется вправо'],['left','Масса сдвинется влево'],['same','Ничего не изменится']])}<div class="sim-metrics"><div><b>${Math.round(p*100)}%</b><small>ошибка одного символа</small></div><div><b>${fmt(vals.slice(0,4).reduce((a,b)=>a+b,0))}</b><small>не более 3 ошибок</small></div></div><div class="bars">${vals.map((v,k)=>`<div class="bar-col"><div class="vertical-meter"><i class="${k<=3?'cool':'warm'}" style="height:${100*v/max}%"></i></div><small>${k}</small></div>`).join('')}</div><div class="control-row"><label for="errorRange">Вероятность ошибки p</label><input id="errorRange" type="range" min="0.01" max="0.5" step="0.01" value="${p}" data-exp="errorP"></div><p class="sim-footnote">Числа снизу — число ошибок. <span class="colored-teal">■</span> 0–3 ошибки · <span class="colored-peach">■</span> 4–10 ошибок</p>`}
function selfIndependenceView(){const p=experiment.selfP,p2=p*p,gap=p-p2,x=35+400*p,y1=180-140*p,y2=180-140*p2;return `<div class="prediction"><b>Прогноз: где p и p² совпадут?</b><div>${[['middle','Только внутри (0,1)'],['edges','На границах'],['all','При любом p']].map(([id,label])=>`<button class="${experiment.prediction===id?'picked':''}" data-predict="${id}">${label}</button>`).join('')}</div>${experiment.prediction!==null?'<small>Прогноз зафиксирован — теперь проверь его ползунком.</small>':''}</div><svg viewBox="0 0 470 210" class="sim-svg" role="img" aria-label="Графики p и p в квадрате"><line x1="35" x2="435" y1="180" y2="180" stroke="#bdb7aa"/><line x1="35" x2="35" y1="40" y2="180" stroke="#bdb7aa"/><line x1="35" x2="435" y1="180" y2="40" stroke="#4258d4" stroke-width="4"/><path d="M35 180 Q235 180 435 40" fill="none" stroke="#e9974d" stroke-width="4"/><line x1="${x}" x2="${x}" y1="${y1}" y2="${y2}" stroke="#59606f" stroke-dasharray="4 4"/><circle cx="${x}" cy="${y1}" r="6" fill="#4258d4"/><circle cx="${x}" cy="${y2}" r="6" fill="#e9974d"/><text x="440" y="183" font-size="11" fill="#777">1</text><text x="28" y="195" font-size="11" fill="#777">0</text><text x="321" y="66" font-size="12" fill="#4258d4">p</text><text x="345" y="116" font-size="12" fill="#b36b2d">p²</text></svg><div class="sim-metrics self-metrics"><div><b>${p.toFixed(2)}</b><small>p = P(E∩E)</small></div><div><b>${p2.toFixed(2)}</b><small>p² = P(E)P(E)</small></div><div class="${gap<.00001?'equal':''}"><b>${gap.toFixed(2)}</b><small>разрыв p−p²</small></div></div><div class="control-row"><label for="selfRange">Вероятность p=${p.toFixed(2)}</label><input id="selfRange" type="range" min="0" max="1" step="0.01" value="${p}" data-exp="selfP"></div><p class="sim-footnote">Синяя прямая показывает p, янтарная кривая — p². Независимость требует их равенства.</p>`}
const urnColors=[['yellow','Ж',2],['green','З',2],['blue','С',3],['red','К',4],['white','Б',4]];
