function diceOrderView(){const dice=[experiment.dice1,experiment.dice2,experiment.dice3],distinct=new Set(dice).size===3,increasing=dice[0]<dice[1]&&dice[1]<dice[2];return `${conceptPrediction('Прогноз: что обязательно для строгого роста?',[['distinct','Все значения различны'],['repeat','Нужен повтор'],['sum','Только большая сумма']])}<div class="dice-lab">${dice.map((value,i)=>`<div><span class="dice-face">${value}</span><label for="dice${i+1}">Кубик ${i+1}</label><input id="dice${i+1}" type="range" min="1" max="6" value="${value}" data-exp="dice${i+1}"></div>`).join('')}</div><div class="lab-status-grid"><div class="${distinct?'pass':'fail'}"><b>${distinct?'✓':'×'} Различны</b><small>${dice.join(', ')}</small></div><div class="${increasing?'pass':'fail'}"><b>${increasing?'✓':'×'} Строго возрастают</b><small>${dice.join(' < ')}</small></div></div><p class="sim-footnote">При фиксированном наборе различных граней возрастающим будет ровно один порядок.</p>`}
function permutationView(){const names=['А','Б','В','Г','Д'],fixed=experiment.permutation.filter((value,i)=>value===i).length;return `${conceptPrediction('Прогноз: сколько перестановок из 120 не имеют совпадений?',[['few','Меньше 40'],['fortyfour','44'],['many','Больше 60']])}<div class="permutation-board">${experiment.permutation.map((value,i)=>`<div class="${value===i?'fixed':''}"><span>${names[i]}</span><i>→</i><b>${names[value]}</b><small>${value===i?'совпало':'другое имя'}</small></div>`).join('')}</div><div class="experiment-action"><button class="btn-main" data-permutation-shuffle="1">Перемешать имена</button><strong class="${fixed?'danger':'safe'}">Фиксированных точек: ${fixed}</strong></div><p class="sim-footnote">Беспорядок — перестановка без единой подсвеченной строки.</p>`}
function vennAtomsView(){const p=experiment.vennP,pair=p*p,only=p-2*pair,valid=only>=-1e-9;return `${conceptPrediction('Прогноз: где проходит верхняя граница p?',[['third','1/3'],['half','1/2'],['twothirds','2/3']])}<div class="atom-visual"><div class="atom-circle a"></div><div class="atom-circle b"></div><div class="atom-circle c"></div><span>тройное<br>пересечение<br>пусто</span></div><div class="sim-metrics atom-metrics"><div><b>${p.toFixed(2)}</b><small>P(A)=P(B)=P(C)</small></div><div><b>${pair.toFixed(3)}</b><small>каждая пара p²</small></div><div class="${valid?'equal':'invalid'}"><b>${only.toFixed(3)}</b><small>только A: p−2p²</small></div></div><div class="control-row"><label for="vennRange">Общая вероятность p=${p.toFixed(2)}</label><input id="vennRange" type="range" min="0" max="0.65" step="0.01" value="${p}" data-exp="vennP"></div><p class="sim-footnote">${valid?'Все показанные массы неотрицательны.':'Отрицательная масса невозможна: такая модель не существует.'}</p>`}
const suitProfiles={3111:[3,1,1,1],2211:[2,2,1,1],4110:[4,1,1,0],2220:[2,2,2,0]};
function suitProfilesView(){const counts=suitProfiles[experiment.suitProfile],covered=counts.every(Boolean),symbols=['♠','♥','♦','♣'];return `${conceptPrediction('Прогноз: сколько профилей покрывают все четыре масти?',[['one','Один'],['two','Два'],['three','Три']])}<div class="profile-tabs">${Object.entries(suitProfiles).map(([id,items])=>`<button class="${experiment.suitProfile===id?'picked':''}" data-suit-profile="${id}">${items.join('+')}</button>`).join('')}</div><div class="suit-counts">${counts.map((count,i)=>`<div class="${i===1||i===2?'red':''}"><b>${symbols[i]}</b><span>${count}</span><small>${count?'карт':'масть пропущена'}</small></div>`).join('')}</div><div class="profile-verdict ${covered?'pass':'fail'}">${covered?'✓ Все четыре масти представлены':'× Не хватает хотя бы одной масти'}</div><p class="sim-footnote">Порядок частей профиля не важен: назначение частей конкретным мастям учитывается отдельно.</p>`}
function childrenView(){const p=experiment.childP,q=1-p,A=p**3+q**3,B=q**3+3*p*q*q,C=1-A,AB=q**3,BC=3*p*q*q;return `${conceptPrediction('Прогноз при p=1/2: сколько пар событий независимы?',[['none','Ни одной'],['two','Две'],['all','Все три']])}<div class="family-strip"><span style="width:${p*100}%">М ${(p*100).toFixed(0)}%</span><span style="width:${q*100}%">Д ${(q*100).toFixed(0)}%</span></div><div class="event-probabilities"><div><b>A</b><span>${A.toFixed(3)}</span><small>все одного пола</small></div><div><b>B</b><span>${B.toFixed(3)}</span><small>не более мальчика</small></div><div><b>C</b><span>${C.toFixed(3)}</span><small>оба пола</small></div></div><div class="intersection-table"><span>A∩B = ${AB.toFixed(3)}</span><span>B∩C = ${BC.toFixed(3)}</span><span>A∩C = 0</span></div><div class="control-row"><label for="childRange">P(мальчик)=${p.toFixed(2)}</label><input id="childRange" type="range" min="0.05" max="0.95" step="0.05" value="${p}" data-exp="childP"></div><p class="sim-footnote">Сравни каждое пересечение с произведением соответствующих вероятностей.</p>`}
function continuityView(){const n=experiment.layerN,layers=Array.from({length:n},(_,i)=>({i:i+1,w:2**-(i+1)})),sum=1-2**-n;return `${conceptPrediction('Прогноз: зачем нужны слои Dₙ?',[['disjoint','Сделать части непересекающимися'],['equal','Сделать их равными'],['finite','Остановить последовательность']])}<div class="continuity-layers">${layers.map(({i,w})=>`<div style="flex:${Math.max(w,.04)}"><b>D${i}</b><small>${w.toFixed(4)}</small></div>`).join('')}</div><div class="sim-metrics"><div><b>${n}</b><small>слоёв открыто</small></div><div><b>${sum.toFixed(4)}</b><small>P(Bₙ)=ΣP(Dⱼ)</small></div><div><b>${(2**-n).toFixed(4)}</b><small>остаток до предела</small></div></div><div class="control-row"><label for="layerRange">Число частичных слоёв</label><input id="layerRange" type="range" min="1" max="8" value="${n}" data-exp="layerN"></div><p class="sim-footnote">Bₙ складывается из первых n непересекающихся слоёв, а их объединение не меняется.</p>`}
const fact=n=>Array.from({length:n},(_,i)=>i+1).reduce((a,b)=>a*b,1);
const labMetrics=items=>`<div class="sim-metrics lab-metrics">${items.map(([value,label,cls=''])=>`<div class="${cls}"><b>${value}</b><small>${label}</small></div>`).join('')}</div>`;
function graphCycleView(){const n=experiment.graphN,total=n*(n-1)/2,cycles=fact(n-1)/2;return `${conceptPrediction('Прогноз: что означает «граф является циклом»?',[['exact','Нужные рёбра есть, лишних нет'],['contains','Достаточно найти цикл'],['tree','Рёбер должно быть n−1']])}<div class="node-ring">${Array.from({length:n},(_,i)=>`<span style="--i:${i};--n:${n}">${i+1}</span>`).join('')}</div>${labMetrics([[cycles,'различных циклов'],[n,'рёбер в цикле'],[total-n,'запрещённых хорд']])}<div class="control-row"><label>Число вершин n=${n}</label><input type="range" min="3" max="8" value="${n}" data-exp="graphN"></div><p class="sim-footnote">Для одного цикла вероятность включает pⁿ и отсутствие ${total-n} остальных рёбер.</p>`}
function diceConditionView(){const filtered=Boolean(experiment.diceFilter);return `${conceptPrediction('Прогноз: что произойдёт с чётностями после условия B?',[['linked','Они станут связанными'],['same','Ничего не изменится'],['impossible','Исходов не останется']])}<div class="outcome-grid dice-grid">${Array.from({length:36},(_,i)=>{const a=Math.floor(i/6)+1,c=i%6+1,even=(a+c)%2===0;return `<span class="${filtered&&!even?'muted':a%2===0&&c%2===0?'hit':''}">${a},${c}</span>`}).join('')}</div><button class="btn-quiet" data-dice-filter="1">${filtered?'Показать все 36 исходов':'Оставить только B: сумма чётна'}</button>${labMetrics([[filtered?'18':'36','исходов в пространстве'],[filtered?'1/2':'1/4','P(A∩C'+(filtered?'|B':'')+')']])}`}
function diagnosticMixView(){const r=experiment.diseaseRate,pa=r*.9+(1-r)*.1,joint=r*.81+(1-r)*.01;return `${conceptPrediction('Прогноз: независимы ли тесты без знания статуса?',[['dependent','Нет, общая причина связывает'],['independent','Да'],['never','Зависимы и внутри групп']])}<div class="mixture-bar"><span style="width:${r*100}%">болезнь</span><span style="width:${(1-r)*100}%">здоровье</span></div>${labMetrics([[pa.toFixed(3),'P(A)=P(C)'],[joint.toFixed(3),'P(A∩C)'],[(pa*pa).toFixed(3),'P(A)P(C)',Math.abs(joint-pa*pa)<1e-6?'equal':'invalid']])}<div class="control-row"><label>Доля больных ${(r*100).toFixed(0)}%</label><input type="range" min="0" max="1" step="0.01" value="${r}" data-exp="diseaseRate"></div>`}
function fixedHeadsView(){const m=experiment.fixedM,n=6;return `${conceptPrediction('Прогноз: зависит ли ответ от номера позиции k?',[['no','Нет, позиции симметричны'],['yes','Да'],['p','Зависит только от p']])}<div class="heads-row">${Array.from({length:n},(_,i)=>`<span class="${i<m?'head':''}">${i<m?'О':'Р'}</span>`).join('')}</div>${labMetrics([[`C(6,${m})`,'равновероятных расположений'],[(m/n).toFixed(3),'шанс орла в любой позиции']])}<div class="control-row"><label>Всего орлов m=${m}</label><input type="range" min="0" max="6" value="${m}" data-exp="fixedM"></div>`}
function conditionalTreeView(){const x=experiment.association;return `${conceptPrediction('Прогноз: когда можно заменить P(C|B) на P(C)?',[['independent','Только при независимости B,C'],['always','Всегда'],['equal','Только если B=C']])}<div class="branch-compare"><div><b>Правильный вес</b><strong>P(C|B)=${x.toFixed(2)}</strong></div><div><b>Вес из формулы</b><strong>P(C)=0.50</strong></div></div>${labMetrics([[Math.abs(x-.5).toFixed(2),'ошибка подмены весов',Math.abs(x-.5)<.001?'equal':'invalid']])}<div class="control-row"><label>Связь внутри B</label><input type="range" min="0.1" max="0.9" step="0.05" value="${x}" data-exp="association"></div>`}
function parityRecurrenceView(){const p=experiment.parityP,n=6,vals=Array.from({length:n+1},(_,i)=>(1+(1-2*p)**i)/2);return `${conceptPrediction('Прогноз: к чему стремится вероятность чётности?',[['half','К 1/2'],['zero','К 0'],['one','К 1']])}<div class="recurrence-bars">${vals.map((v,i)=>`<div><i style="height:${v*100}%"></i><small>${i}</small></div>`).join('')}</div>${labMetrics([[vals[n].toFixed(4),`p${n}`],[(1-2*p).toFixed(2),'множитель отклонения']])}<div class="control-row"><label>P(орёл)=${p.toFixed(2)}</label><input type="range" min="0.05" max="0.95" step="0.05" value="${p}" data-exp="parityP"></div>`}
function coinMixtureView(){const p=experiment.biasedP,marg=(.5+p)/2,joint=(.25+p*p)/2;return `${conceptPrediction('Прогноз: что делает общий выбор монеты?',[['links','Связывает два броска в смеси'],['nothing','Не влияет'],['exclusive','Делает орлы невозможными вместе']])}<div class="coin-layers"><div><b>Честная</b><span>p=0,50</span></div><div><b>Смещённая</b><span>p=${p.toFixed(2)}</span></div></div>${labMetrics([[marg.toFixed(3),'P(A)=P(C)'],[joint.toFixed(3),'P(A∩C)'],[(marg*marg).toFixed(3),'P(A)P(C)',Math.abs(joint-marg*marg)<1e-6?'equal':'invalid']])}<div class="control-row"><label>Параметр смещённой монеты</label><input type="range" min="0.05" max="0.95" step="0.05" value="${p}" data-exp="biasedP"></div>`}
function subsetBitsView(){const p=experiment.subsetP,states=Array.from({length:8},(_,i)=>i.toString(2).padStart(3,'0')),allowed=states.filter(s=>s!=='111');return `${conceptPrediction('Прогноз: как перейти от одного элемента к n?',[['power','Возвести локальную вероятность в n'],['sum','Умножить её на n'],['same','Оставить без изменения']])}<div class="bit-states">${states.map(s=>`<span class="${s==='111'?'forbidden':'allowed'}">${s}</span>`).join('')}</div>${labMetrics([[(1-p**3).toFixed(3),'не попасть в A∩B∩C'],[(p+(1-p)**3).toFixed(3),'локально A∪B⊆C'],[allowed.length,'разрешённых битовых троек при p=1/2']])}<div class="control-row"><label>Вероятность включения p=${p.toFixed(2)}</label><input type="range" min="0" max="1" step="0.05" value="${p}" data-exp="subsetP"></div>`}
function parityDiceView(){const f=experiment.parityFace,vals=[f,2,3,4],sum=vals.reduce((a,b)=>a+b,0);return `${conceptPrediction('Прогноз: сколько паритетных строк дают чётную сумму?',[['half','Ровно половина'],['quarter','Четверть'],['all','Все']])}<div class="heads-row dice-values">${vals.map(v=>`<span>${v}</span>`).join('')}</div><div class="profile-verdict ${sum%2===0?'pass':'fail'}">Сумма ${sum} — ${sum%2===0?'чётная':'нечётная'}</div><div class="control-row"><label>Первая грань: ${f}</label><input type="range" min="1" max="6" value="${f}" data-exp="parityFace"></div><p class="sim-footnote">Смена первой грани 1↔2, 3↔4, 5↔6 меняет класс паритета.</p>`}
function bagMixtureView(){const w=experiment.bagWeight,joint=w*3/8+(1-w)*1/8;return `${conceptPrediction('Прогноз: что происходит при равной смеси?',[['cancel','Зависимости компенсируются'],['stronger','Зависимость усиливается'],['none','Маргиналы исчезают']])}<div class="bag-cells"><div><b>M₁</b><span>11: 3/8</span></div><div><b>M₂</b><span>11: 1/8</span></div></div>${labMetrics([[joint.toFixed(3),'P(A∩C) в смеси'],['0.250','P(A)P(C)',Math.abs(joint-.25)<1e-6?'equal':'invalid']])}<div class="control-row"><label>Вес первого мешка ${(w*100).toFixed(0)}%</label><input type="range" min="0" max="1" step="0.05" value="${w}" data-exp="bagWeight"></div>`}
function bipartiteCycleView(){const n=experiment.bipN,count=fact(n)*fact(n-1)/2,total=n*n;return `${conceptPrediction('Прогноз: сколько красных рёбер нужно циклу?',[['twon','2n'],['n','n'],['all','n²']])}<div class="bipartite-nodes"><div>${Array.from({length:n},(_,i)=>`<span>L${i+1}</span>`).join('')}</div><i>⇄</i><div>${Array.from({length:n},(_,i)=>`<span>R${i+1}</span>`).join('')}</div></div>${labMetrics([[count,'гамильтоновых циклов'],[2*n,'красных рёбер'],[total-2*n,'остальных рёбер']])}<div class="control-row"><label>Размер доли n=${n}</label><input type="range" min="2" max="6" value="${n}" data-exp="bipN"></div>`}
const choose=(n,k)=>k<0||k>n?0:fact(n)/(fact(k)*fact(n-k));
function chapter3LabView(mode){const k=experiment.c3K,p=experiment.biasedP;
 const prediction=conceptPrediction('Сначала сделай прогноз, затем проверь ползунком.',[['structure','Структура важнее чисел'],['uniform','Все клетки равны'],['none','Связи нет']]);
 let visual='',metrics=[],label='Параметр',min=1,max=6,value=k,key='c3K';
 if(mode==='jointLaw'){const outcomes=[['РР','0,0'],['РО','1,0'],['ОР','1,0'],['ОО','2,1']],hit=outcomes[k%4];visual=`<div class="c3-table">${outcomes.map((o,i)=>`<span class="${i===k%4?'hit':''}"><b>${o[0]}</b><small>(${o[1]})</small></span>`).join('')}</div>`;metrics=[[hit[0],'исход'],[`(${hit[1]})`,'клетка (ξ,η)'],['3','ненулевые клетки']];label='Выделенный исход';min=0;max=3}
 else if(mode==='bernoulliFunctions'){value=p;key='biasedP';min=0;max=1;label=`p=${p.toFixed(2)}`;visual=`<div class="c3-table"><span><b>ξ=0</b><small>η=1, ζ=0</small></span><span><b>ξ=1</b><small>η=0, ζ=0</small></span></div>`;metrics=[[(1-p).toFixed(2),'масса (0,1,0)'],[p.toFixed(2),'масса (1,0,0)'],['ζ≡0','инвариант']]}
 else if(mode==='geometricGrid'){visual=`<div class="c3-grid">${Array.from({length:25},(_,i)=>{const x=i%5+1,y=Math.floor(i/5)+1;return `<span class="${Math.min(x,y)<=k?'hit':''}">${x},${y}</span>`}).join('')}</div>`;metrics=[[`1−4^−${k}`,'P(min≤k)'],['1/3','P(η>ξ)'],['≈0.607','P(ξ делит η)']]}
 else if(mode==='binomialSum'){const n=3,m=k,total=n+m;visual=`<div class="c3-blocks"><div>${Array.from({length:n},()=>'<i></i>').join('')}</div><b>+</b><div>${Array.from({length:m},()=>'<i></i>').join('')}</div></div>`;metrics=[[n,'первый блок'],[m,'второй блок'],[`Bin(${total},p)`,'сумма']];label='Размер второго блока';max=7}
 else if(mode==='coinThinning'){value=p;key='biasedP';min=0;max=1;label=`p=${p.toFixed(2)}`;visual=`<div class="c3-filters"><span>n монет</span><b>× p</b><span>первая решка</span><b>× p</b><span>вторая решка</span></div>`;metrics=[[p.toFixed(2),'p'],[(p*p).toFixed(3),'p²'],[`Bin(n, ${(p*p).toFixed(2)})`,'итог']]}
 else if(mode==='walkPosition'){const n=k,points=Array.from({length:n+1},(_,i)=>-n+2*i);visual=`<div class="c3-axis">${points.map(x=>`<span>${x}</span>`).join('')}</div>`;metrics=[[n,'шагов'],[points.length,'достижимых точек'],[n%2?'нечётный':'чётный','паритет x']];label='Число шагов n';max=10}
 else if(mode==='reflection'){visual=`<svg class="c3-path" viewBox="0 0 320 120"><polyline points="10,35 60,15 110,55 160,75 210,55 260,35 310,15"/><polyline class="reflected" points="10,85 60,105 110,65 160,45 210,55 260,35 310,15"/><line x1="5" y1="60" x2="315" y2="60"/></svg>`;metrics=[[k,'момент касания τ'],['1 → −1','старт'],['тот же','финиш']];label='Первое касание';max=5}
 else if(mode==='ballot'){const b=k,a=k+2,n=a+b,good=Math.round((a-b)/n*choose(n,a));visual=`<div class="c3-balance"><span>Все с первым ↑<b>${choose(n-1,a-1)}</b></span><em>−</em><span>плохие<b>${choose(n-1,a)}</b></span><em>=</em><span class="hit">хорошие<b>${good}</b></span></div>`;metrics=[[a,'подъёмов a'],[b,'спусков b'],[good,'положительных']];label='Число спусков b';max=5}
 else {const threshold=k,minWith=1-Math.pow((10-threshold)/10,5),maxWith=Math.pow(threshold/10,5);visual=`<div class="c3-cdf"><i style="width:${minWith*100}%"></i><i style="width:${maxWith*100}%"></i></div>`;metrics=[[threshold,'порог k'],[minWith.toFixed(3),'F минимума'],[maxWith.toFixed(3),'F максимума']];label='Порог k';max=10}
 return `${prediction}${visual}${labMetrics(metrics)}<div class="control-row"><label>${label}</label><input type="range" min="${min}" max="${max}" step="${key==='biasedP'?'0.05':'1'}" value="${value}" data-exp="${key}"></div>`;
}
function chapter4LabView(mode){const k=experiment.c3K,p=experiment.biasedP,n=Math.max(2,k);let title='',cells=[],metrics=[],key='c3K',value=k,min=1,max=8,label='Параметр';
 if(mode==='conditionalChain'){title='C → B∩C → A∩B∩C';cells=['P(ABC)/P(BC)','×','P(BC)/P(C)','→','P(ABC)/P(C)'];metrics=[['P(BC)','сокращается'],[n,'масса слоя'],['2','знаменателя']]}
 else if(mode==='permutationFibers'){title='Слои ξ';cells=['{123}','{132,213,321}','{231,312}'];metrics=[['3','слоя'],['6','перестановок'],['ξ≠2','ограничение']]}
 else if(mode==='jointProduct'){title='Совместная клетка = строка × столбец';cells=Array.from({length:8},(_,i)=>`(${i%4},${Math.floor(i/4)+1})`);metrics=[[n,'n'],[p.toFixed(2),'p'],['p₁·p₂','масса']]}
 else if(mode==='uniformStopping'){title='Одна последовательность — две статистики';cells=Array.from({length:n},(_,i)=>`${i+1}: ${(i/(n+1)).toFixed(2)}`);metrics=[[n,'координат'],[`Bin(${n},p)`,'счётчик'],['0…n','первый успех']]}
 else if(mode==='poissonThinning'){key='biasedP';value=p;min=0;max=1;label=`Доля p=${p.toFixed(2)}`;title='Poi(λ) → Bernoulli-фильтр → Poi(λp)';cells=['поток','× p','оставшиеся'];metrics=[[p.toFixed(2),'доля'],[(4*p).toFixed(2),'λp при λ=4'],['Poi','тип закона']]}
 else if(mode==='shiftMixture'){title='Три сдвинутые копии';cells=['F(x+1)','F(x)','F(x−1)'];metrics=[[n,'порог x'],['1/3','вес'],['среднее','итог']]}
 else if(mode==='factoryRisk'){key='biasedP';value=p;min=.01;max=.08;label=`Риск третьего ${(p*100).toFixed(1)}%`;title='Заводы и уровни риска';cells=['B₁: 1%','B₂: 4%',`B₃: ${(p*100).toFixed(1)}%`];metrics=[['50/30/20','доли'],[p===.04?'нет':'да','различим B₃'],[(.005+.012+.2*p).toFixed(3),'общий риск']]}
 else if(mode==='poissonConvolution'){title=`Диагональ суммы x=${n}`;cells=Array.from({length:n+1},(_,i)=>`(${i},${n-i})`);metrics=[[n+1,'клеток'],['μ+ν','параметр'],['бином','свёртка']]}
 else if(mode==='geometricMemory'){title=`Отбрасываем ${n} неудач`;cells=[...Array.from({length:n},()=> '×'),'→','новый старт'];metrics=[[n,'прошло'],['p','следующий успех'],['Geo(p)','остаток']]}
 else {key='biasedP';value=p;min=.02;max=.5;label=`δ=${p.toFixed(2)}`;title='Редкие события по масштабам';cells=['один: O(δ)','пара: O(δ²)','три: O(δ³)'];metrics=[[p.toFixed(2),'δ'],[(p*p).toFixed(3),'δ²'],['Σλⱼ','главный коэффициент']]}
 return `${conceptPrediction('Как изменится структура при движении параметра?',[['structure','Сохранится закон'],['uniform','Все сравняется'],['none','Связь исчезнет']])}<h4 class="c4-lab-title">${title}</h4><div class="c4-cells">${cells.map(x=>`<span>${x}</span>`).join('')}</div>${labMetrics(metrics)}<div class="control-row"><label>${label}</label><input type="range" min="${min}" max="${max}" step="${key==='biasedP'?'.01':'1'}" value="${value}" data-exp="${key}"></div>`}
